/*===========================================================================
  RegTrack Insights - v4 free tier
  05_verify_deployed.sql - READ-ONLY. Run any time on UAT, prod or demo.
  Per procedure:
    NEW        - this pack (v4, including the 2026-10-07 licence end-date fix)
    V4 EARLY   - v4 as first deployed 2026-10-06 (without the licence fix)
    OLD        - before v4 (dashboard rules)
    OTHER      - none of these: tell the author
  Last line: DEPLOYED (all 8 NEW), or what is still missing.
  SQL Server stores 'CREATE OR ALTER PROCEDURE' as 'CREATE   PROCEDURE'; the
  fingerprints below account for that. Changes nothing, never THROWs.
===========================================================================*/
SET NOCOUNT ON;
DECLARE @v TABLE (Name SYSNAME PRIMARY KEY, DeployFile VARCHAR(4), NewSha VARCHAR(66), EarlySha VARCHAR(66), OldSha VARCHAR(66));
