DECLARE @r TABLE (Name SYSNAME, DeployFile VARCHAR(4), Version VARCHAR(10), LastModified DATETIME);
INSERT @r
SELECT v.Name, v.DeployFile,
       CASE WHEN h.Sha IS NULL THEN 'MISSING' WHEN h.Sha = v.NewSha THEN 'NEW' WHEN h.Sha = v.EarlySha THEN 'V4 EARLY'
            WHEN h.Sha = v.OldSha THEN 'OLD' ELSE 'OTHER' END,
       o.modify_date
FROM @v v
LEFT JOIN sys.objects o ON o.object_id = OBJECT_ID('dbo.' + v.Name)
OUTER APPLY (SELECT CONVERT(VARCHAR(66), HASHBYTES('SHA2_256', CAST(m.definition AS VARBINARY(MAX))), 1) AS Sha
             FROM sys.sql_modules m WHERE m.object_id = OBJECT_ID('dbo.' + v.Name)) h;
SELECT DeployFile, Name, Version, LastModified FROM @r ORDER BY DeployFile, Name;
SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM @r WHERE Version <> 'NEW') THEN 'DEPLOYED - all 8 procedures are this v4 pack'
            ELSE 'NOT FULLY DEPLOYED - not yet NEW: ' + (SELECT STRING_AGG(Name + ' (' + Version + ', file ' + DeployFile + ')', ', ') FROM @r WHERE Version <> 'NEW')
       END AS Result;